<?php define('SKIP_ADMIN_CHECK',true); require_once __DIR__.'/includes/auth.php';if(!empty($_SESSION['admin_id'])){header('Location:index.php');exit;}require_once __DIR__.'/../config/database.php';$e='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=db()->prepare('SELECT * FROM admins WHERE username=?');$s->execute([$_POST['username']??'']);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];header('Location:index.php');exit;}$e='用户名或密码错误';}?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>后台登录</title><link rel="stylesheet" href="assets/admin.css"></head><body><div class="wrap login"><div class="card"><h1>后台登录</h1><?php if($e):?><div class="notice"><?=$e?></div><?php endif;?><form method="post"><div class="field"><label>用户名</label><input name="username" required></div><br><div class="field"><label>密码</label><input type="password" name="password" required></div><br><button class="btn primary">登录</button></form></div></div></body></html>